  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Why We Have Government$j$, $j${"readings": [{"title": "Romans 13 (King James Version)", "url": "/portal/bible/Romans/13"}], "body": "Government is the system of people and rules that makes laws, keeps order, settles disputes and protects the public. Without it, people would live in disorder, and the strong would take advantage of the weak. Scripture says in Romans 13:1 that every soul should be subject unto the higher powers, for the powers that be are ordained of God.\n\nGovernments have four basic purposes: to keep order and safety, to protect rights, to provide services such as roads and schools, and to settle conflicts fairly. Political thinkers called this idea a social contract. John Locke, an English philosopher, taught that people hold natural rights to life, liberty and property, and that a government earns its power from the consent of the governed.\n\nGovernments take different forms. In a monarchy, a king or queen rules. In an autocracy or dictatorship, one person holds all power. In a democracy, the people hold power; in a direct democracy they vote on laws themselves, and in a republic, also called a representative democracy, they elect leaders to act for them. The United States is a constitutional republic, which means that elected officials must follow a written constitution.\n\nYour task: (1) List the four purposes of government. (2) Define social contract and consent of the governed. (3) Explain the difference between a direct democracy and a republic, and tell which one the United States is.\n\nFlorida standards: SS.912.CG.1.1, SS.912.CG.1.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.CG.1.1, SS.912.CG.1.2", "script": "Welcome to United States Government. I am Dr. Alex L. Jenkins Sr., and I am glad to teach you how our nation works. Listen, a citizen who understands government is a citizen who can serve well, speak wisely and vote with a clear conscience.\n\nWe start with a simple question. Why do we have government at all? Government is the system of people and rules that makes laws, keeps order, settles disputes and protects the public. Without it the strong would take advantage of the weak. Romans 13:1 tells us that the powers that be are ordained of God.\n\nNow watch this. Governments have four basic purposes. Keep order and safety. Protect rights. Provide services like roads and schools. And settle conflicts fairly.\n\nLook at the big idea behind it, the social contract. John Locke taught that people have natural rights to life, liberty and property, and that a government gets its power from the consent of the governed.\n\nGovernments come in different forms. A monarchy has a king or queen. A dictatorship has one ruler with all power. In a direct democracy the people vote on the laws themselves. In a republic they elect leaders to act for them. The United States is a constitutional republic, because our leaders must follow a written constitution.\n\nYour task is to list the four purposes, define the social contract, and explain direct democracy and republic. Take the four question check. Know your government. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Why We Have Government$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 From the Declaration to the Constitution$j$, $j${"readings": [{"title": "Psalm 33 (King James Version)", "url": "/portal/bible/Psalms/33"}], "body": "On July 4, 1776, the Continental Congress adopted the Declaration of Independence, written mainly by Thomas Jefferson. It states that all men are created equal and are endowed by their Creator with unalienable rights, among them life, liberty and the pursuit of happiness, and that governments get their just powers from the consent of the governed. It then lists grievances against King George III.\n\nAfter the war the states created the Articles of Confederation, ratified in 1781. They formed a weak national government with no power to tax, no president, no national court, and a rule that nine of thirteen states must agree to pass a law. Changing the Articles needed every state. Shays' Rebellion in Massachusetts in 1786 and 1787 showed that the nation could not even put down an uprising.\n\nIn the summer of 1787, 55 delegates met in Philadelphia, with George Washington presiding, and wrote an entirely new Constitution instead of repairing the old one. The Great Compromise gave the House seats by population and the Senate two seats per state. The Three Fifths Compromise counted three fifths of the enslaved population for representation and taxes, a moral wrong that denied the full humanity of enslaved people. After a debate between Federalists and Antifederalists, the Constitution was ratified in 1788.\n\nYour task: (1) Name two ideas from the Declaration. (2) List three weaknesses of the Articles. (3) Explain the Great Compromise.\n\nFlorida standards: SS.912.CG.1.1, SS.912.CG.1.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.CG.1.1, SS.912.CG.1.3", "script": "Now we go back to the beginning. Listen, on July 4, 1776, the Continental Congress adopted the Declaration of Independence, written mainly by Thomas Jefferson. It says that all men are created equal and are endowed by their Creator with unalienable rights, life, liberty and the pursuit of happiness. It says governments get their just powers from the consent of the governed.\n\nNow watch this. After the war, the states created the Articles of Confederation in 1781. It was a weak plan. No power to tax. No president. No national court. Nine of thirteen states had to agree to pass a law. In 1786 and 1787, Shays' Rebellion in Massachusetts showed that the nation could not even put down an uprising.\n\nLook at what happened next. In the summer of 1787, fifty five delegates met in Philadelphia, with George Washington presiding. They decided to write a whole new Constitution. The Great Compromise gave the House seats by population and the Senate two seats for every state. The Three Fifths Compromise counted enslaved people as three fifths for representation and taxes. We tell the truth about that. It was a moral wrong that denied their full humanity.\n\nFederalists supported the new Constitution, and Antifederalists feared a strong national government. It was ratified in 1788.\n\nYour task is to name two ideas from the Declaration, list three weaknesses of the Articles, and explain the Great Compromise. Take the four question check. Truth builds a strong nation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 From the Declaration to the Constitution$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 The Constitution and Its Principles$j$, $j${"readings": [{"title": "Isaiah 33 (King James Version)", "url": "/portal/bible/Isaiah/33"}], "body": "The Constitution opens with the Preamble, which begins, We the People of the United States, in order to form a more perfect Union. These words show that the people, not a king, hold the highest authority. The seven articles then set up the three branches and the relations between the states.\n\nSeven principles hold the Constitution together. First, popular sovereignty: power comes from the people. Second, limited government: government may do only what the Constitution allows. Third, the rule of law: everyone, including officials, must obey the law. Fourth, separation of powers: Article I gives lawmaking to Congress, Article II gives enforcing to the President, and Article III gives judging to the courts. Fifth, checks and balances: each branch can limit the others, as when the President vetoes a bill or the Senate rejects a nominee. Sixth, federalism: power is shared between the national government and the states. Seventh, individual rights.\n\nThe founders feared that power gathered in a few hands would be abused. James Madison wrote in Federalist No. 51 that if men were angels, no government would be necessary. Scripture agrees that leaders are fallen people: Isaiah 33:22 says the LORD is our judge, the LORD is our lawgiver, the LORD is our king, a threefold description that reminds us that only God holds all authority.\n\nYour task: (1) Explain what We the People means. (2) Define separation of powers and checks and balances. (3) Give one example of a check.\n\nFlorida standards: SS.912.CG.1.3, SS.912.CG.4.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.CG.1.3, SS.912.CG.4.1", "script": "Now let's open the Constitution. Listen, it begins with the Preamble, We the People of the United States, in order to form a more perfect Union. Those words matter. The people, not a king, hold the highest authority.\n\nSeven principles hold the Constitution together. Popular sovereignty, power comes from the people. Limited government, government can do only what the Constitution allows. The rule of law, everyone, including officials, must obey the law.\n\nNow watch this. Separation of powers. Article I gives lawmaking to Congress. Article II gives enforcing to the President. Article III gives judging to the courts. Then checks and balances, so each branch can limit the others. The President can veto a bill. The Senate can reject a nominee. The courts can strike down a law that violates the Constitution. Then federalism, power shared between the nation and the states. And individual rights.\n\nWhy did the founders do this? They feared power gathered in a few hands. James Madison wrote that if men were angels, no government would be necessary. Isaiah 33:22 says the LORD is our judge, our lawgiver and our king. Only God holds all authority, so human power must be divided and watched.\n\nYour task is to explain We the People, define separation of powers and checks and balances, and give an example of a check. Take the four question check. Divided power protects freedom. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 The Constitution and Its Principles$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 The Bill of Rights and the Amendments$j$, $j${"readings": [{"title": "Galatians 5 (King James Version)", "url": "/portal/bible/Galatians/5"}], "body": "Many Americans supported the Constitution only after promises of a list of protected rights. Antifederalists wanted written guarantees. The first ten amendments, called the Bill of Rights, were ratified on December 15, 1791.\n\nThe First Amendment protects five freedoms: religion, speech, press, assembly and petition. The Second protects the right to keep and bear arms. The Third limits the quartering of soldiers. The Fourth protects against unreasonable searches and seizures. The Fifth guarantees due process and protects against self incrimination. The Sixth guarantees a speedy, public trial and a lawyer. The Seventh protects jury trial in civil cases. The Eighth bans cruel and unusual punishment. The Ninth says other rights remain with the people, and the Tenth reserves other powers to the states or the people.\n\nThe Constitution can be changed. Article V says an amendment must be proposed by two thirds of both houses of Congress and ratified by three fourths of the states. There are 27 amendments. The Thirteenth (1865) ended slavery, the Fourteenth (1868) defined citizenship and promised equal protection, the Fifteenth (1870) protected voting regardless of race, the Nineteenth (1920) gave women the vote, and the Twenty Sixth (1971) set the voting age at 18.\n\nGalatians 5:1 says, Stand fast therefore in the liberty wherewith Christ hath made us free. Earthly liberty is a gift to protect.\n\nYour task: (1) Name the five freedoms of the First Amendment. (2) Explain how an amendment is made. (3) Choose one later amendment and tell what it changed.\n\nFlorida standards: SS.912.CG.2.1, SS.912.CG.2.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.CG.2.1, SS.912.CG.2.2", "script": "Now we study the Bill of Rights. Listen, many Americans agreed to the Constitution only after a promise to add a list of protected rights. The first ten amendments were ratified on December 15, 1791.\n\nThe First Amendment protects five freedoms. Religion, speech, press, assembly and petition. The Fourth protects against unreasonable searches. The Fifth guarantees due process. The Sixth guarantees a speedy, public trial and a lawyer. The Eighth bans cruel and unusual punishment. The Tenth reserves other powers to the states and the people.\n\nNow watch this. The Constitution can be changed. Under Article V, an amendment must be proposed by two thirds of both houses of Congress and ratified by three fourths of the states. That is hard on purpose. There are twenty seven amendments.\n\nLook at some later ones. The Thirteenth in 1865 ended slavery. The Fourteenth in 1868 defined citizenship and promised equal protection. The Fifteenth in 1870 protected the vote regardless of race. The Nineteenth in 1920 gave women the vote. The Twenty Sixth in 1971 set the voting age at eighteen.\n\nGalatians 5:1 says, Stand fast therefore in the liberty wherewith Christ hath made us free. Liberty is a gift to protect.\n\nYour task is to name the five freedoms, explain how an amendment is made, and tell what one amendment changed. Take the four question check. Guard your freedoms. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 The Bill of Rights and the Amendments$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Foundations of American Government$j$, $j${"prompt": "Write a report of at least 250 words on the foundations of American government. Use complete sentences and label each part. Proverbs 14:34 says, Righteousness exalteth a nation: but sin is a reproach to any people.\n\nPart 1: Explain the purposes of government and the idea of the consent of the governed.\nPart 2: Describe why the Articles of Confederation failed and how the Constitution fixed two of the problems.\nPart 3: Explain three principles of the Constitution (for example popular sovereignty, separation of powers, checks and balances, federalism or limited government) and give an example of each.\nPart 4: Explain the purpose of the Bill of Rights and describe two rights it protects.\nPart 5: Tell how amendments are made and explain one amendment that expanded freedom or equality.", "rubric": "100 points. Part 1: 15 points. Part 2: 25 points. Part 3: 25 points. Part 4: 15 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Foundations of American Government$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Why Power Must Be Limited$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains why the founders divided power among branches, (2) tells which freedom in the Bill of Rights you value most and why, (3) describes one way a citizen can protect that freedom, and (4) connects your answer to Proverbs 29:2, which says, When the righteous are in authority, the people rejoice: but when the wicked beareth rule, the people mourn. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it hard to amend the Constitution, and is that a good thing? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Why Power Must Be Limited$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Why We Have Government$j$, $j${"questions": [{"q": "A government gets its just power from:", "options": ["The consent of the governed", "Its oldest family", "Its army alone", "Its wealth"]}, {"q": "The United States is best described as:", "options": ["A direct democracy only", "A monarchy", "A dictatorship", "A constitutional republic"]}, {"q": "In a direct democracy:", "options": ["A court makes the laws", "A king makes the laws", "The people vote on laws themselves", "No one votes"]}, {"q": "Which is a basic purpose of government?", "options": ["Choose every citizen's job", "Protect rights and keep order", "Set church doctrine", "Own all businesses"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Why We Have Government$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,2,1}'::int[], array[$j$Locke taught that government rests on the consent of the governed.$j$,$j$Elected leaders must follow a written constitution.$j$,$j$In a direct democracy citizens decide laws directly.$j$,$j$Government exists to keep order, protect rights, provide services and settle conflicts.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Why We Have Government$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: From the Declaration to the Constitution$j$, $j${"questions": [{"q": "The Declaration of Independence was adopted in:", "options": ["1865", "1776", "1787", "1620"]}, {"q": "A weakness of the Articles of Confederation was that Congress could not:", "options": ["Meet at all", "Elect a king", "Print money for the states", "Tax the people"]}, {"q": "The Great Compromise created:", "options": ["A House based on population and a Senate with equal states", "A king", "A national church", "Two presidents"]}, {"q": "The Constitutional Convention met in:", "options": ["Boston in 1776", "Washington in 1800", "Philadelphia in 1787", "New York in 1865"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: From the Declaration to the Constitution$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,0,2}'::int[], array[$j$It was adopted on July 4, 1776.$j$,$j$The Articles gave Congress no power to tax.$j$,$j$It balanced large and small states.$j$,$j$Delegates met in Philadelphia in the summer of 1787.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: From the Declaration to the Constitution$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: The Constitution and Its Principles$j$, $j${"questions": [{"q": "The Preamble begins with the words:", "options": ["All men are created equal", "In Congress Assembled", "We the People", "By the King's Order"]}, {"q": "Separation of powers divides government into:", "options": ["Four courts", "Two political parties", "Legislative, executive and judicial branches", "Three states"]}, {"q": "A presidential veto is an example of:", "options": ["Popular sovereignty", "Federalism", "Checks and balances", "A constitutional amendment"]}, {"q": "Limited government means:", "options": ["Citizens have no rights", "Government may do only what the Constitution allows", "Government has no laws", "Only one branch exists"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The Constitution and Its Principles$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,2,1}'::int[], array[$j$We the People shows that authority comes from the people.$j$,$j$Congress makes laws, the President enforces them, and the courts judge.$j$,$j$The veto lets the President check Congress.$j$,$j$The Constitution limits what government may do.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: The Constitution and Its Principles$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: The Bill of Rights and the Amendments$j$, $j${"questions": [{"q": "The first ten amendments are called:", "options": ["The Preamble", "The Bill of Rights", "The Federalist Papers", "The Articles"]}, {"q": "The First Amendment protects:", "options": ["The right to a lawyer", "Only speech", "The right to vote", "Religion, speech, press, assembly and petition"]}, {"q": "To ratify an amendment, how many states must approve?", "options": ["All of them", "One third", "Three fourths", "One half"]}, {"q": "The Nineteenth Amendment gave:", "options": ["Eighteen year olds the vote", "Slaves freedom", "Women the right to vote", "Citizens a right to bear arms"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Bill of Rights and the Amendments$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,2,2}'::int[], array[$j$They were ratified in 1791.$j$,$j$These are the five First Amendment freedoms.$j$,$j$Article V requires three fourths of the states.$j$,$j$It was ratified in 1920.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Bill of Rights and the Amendments$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Foundations of American Government$j$, $j${"questions": [{"q": "The Declaration of Independence says governments get their just powers from:", "options": ["The king", "The courts", "The consent of the governed", "The army"]}, {"q": "Which document created a weak national government before 1787?", "options": ["The Mayflower Compact", "The Articles of Confederation", "The Emancipation Proclamation", "The Bill of Rights"]}, {"q": "Who presided over the Constitutional Convention?", "options": ["George Washington", "Thomas Jefferson", "Benjamin Franklin", "John Adams"]}, {"q": "Federalism means:", "options": ["Power is shared between the national government and the states", "Power belongs to one branch", "All power is national", "All power is local"]}, {"q": "Checks and balances allow:", "options": ["Each branch to limit the others", "States to ignore laws", "One branch to rule", "Citizens to skip taxes"]}, {"q": "The Bill of Rights was ratified in:", "options": ["1865", "1776", "1791", "1920"]}, {"q": "An amendment must be proposed by:", "options": ["The President alone", "Two thirds of both houses of Congress", "The Supreme Court", "One state"]}, {"q": "The Fourteenth Amendment promised:", "options": ["Equal protection of the laws", "A national bank", "Prohibition", "An income tax"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of American Government$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,0,0,2,1,0}'::int[], array[$j$Jefferson wrote that just powers come from the consent of the governed.$j$,$j$The Articles of Confederation were ratified in 1781.$j$,$j$Washington presided in 1787.$j$,$j$The Constitution divides power between levels of government.$j$,$j$Each branch can check the others.$j$,$j$The first ten amendments became law in 1791.$j$,$j$Article V sets this requirement.$j$,$j$It defined citizenship and promised equal protection.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of American Government$j$ on conflict (item_id) do nothing;
